// Function to determine maximum element in an array 
def findMax(arr, n): 
    max = arr[0] 

    for i in range(1, n): 
        if arr[i] > max: 
            max = arr[i] 
    return max

def BubbleSort(list): 
    for i in range(len(list)-1): 
        for j in range(0, len(list)-1-i): 
            if list[j] > list[j+1]: 
                list[j], list[j+1] = list[j+1], list[j] 
    return list
